nta.declaration:
broadcast chan tick;          // discrete clock tick (Clock -> Scheduler)

// ---- Parameters ----
const int Tp   = 4;           // periodic task: period
const int Cp   = 1;           // periodic task: worst-case execution time
const int Dp   = 4;           // periodic task: relative deadline
const int Cs   = 2;           // server capacity
const int Ts   = 5;           // server period
const int QMAX = 3;           // aperiodic queue capacity
const int H    = 22;          // horizon (bounds the verification state space)

// ---- Periodic task state (HIGH priority) ----
int  pRem = 0;                // remaining execution of current job
int  pDl  = 0;                // ticks left until current job's deadline
bool pAct = false;            // is a periodic job pending?

// ---- Sporadic Server + aperiodic state (LOWER priority) ----
int  budget   = Cs;           // current server capacity
int  queue    = 0;            // pending aperiodic jobs  (THE QUEUE)
int  apRem    = 0;            // remaining execution of job in service
int  consumed = 0;            // capacity used in current active period
int  replCd   = 0;            // ticks until pending replenishment (0 = none)
int  replAmt  = 0;            // amount to restore
bool srvAct   = false;        // is a server active period open?

// ---- Observation ----
int  now    = 0;              // current discrete time
bool miss   = false;          // true once any deadline is missed
int  served = 0;              // aperiodic jobs completed

// Deterministic aperiodic arrival schedule: number of jobs arriving at time t.
int arrivals(int t) {
    if (t == 3)  return 2;
    if (t == 12) return 1;
    return 0;
}

// One atomic time step.
void tick_update() {
    int a;
    if (now > H) return;                          // freeze after the horizon

    // (1) replenishment fires
    if (replCd > 0) {
        replCd--;
        if (replCd == 0) { budget += replAmt; replAmt = 0; }
    }
    // (2) periodic release
    if (now % Tp == 0) {
        if (pRem > 0) miss = true;                // previous job unfinished
        pRem = Cp; pDl = Dp; pAct = true;
    }
    // (3) aperiodic arrivals -> enqueue (bounded by QMAX)
    a = arrivals(now);
    while (a > 0) {
        if (queue < QMAX) queue++;
        a--;
    }
    // (4) schedule ONE unit of work, fixed priority: periodic > server
    if (pAct && pRem > 0) {
        pRem--;
        if (pRem == 0) pAct = false;
        // server stays ACTIVE during higher-priority preemption (no consumption)
    } else {
        if (apRem == 0 && queue > 0) { queue--; apRem = 1; }   // take next job
        if (apRem > 0 && budget > 0) {
            if (!srvAct && replCd == 0) {         // open a new active period
                srvAct = true; consumed = 0; replCd = Ts;      // RT = now + Ts
            }
            apRem--; budget--; consumed++; replAmt = consumed; // RA = consumed
            if (apRem == 0) served++;
        }
        if (srvAct && apRem == 0 && queue == 0) srvAct = false; // server idle
    }
    // (5) deadline check
    if (pAct && pRem > 0) {
        pDl--;
        if (pDl < 0) miss = true;
    }
    now++;
}

nta.system:
clk   = Clock();
sched = Scheduler();
system clk, sched;
